29→test("apply is idempotent: already-private rejected asset is unchanged", () => {
30→  const plan = planVisibility({ mode: "apply", baseline, current: { [WRONG]: HIDDEN, [RIGHT]: "team", [PEND]: "team" } });
31→  assert.deepEqual(plan.changes, []);
32→});
33→
34→test("reset restores the baseline regardless of decisions", () => {
35→  const plan = planVisibility({ mode: "reset", baseline, current: { [WRONG]: HIDDEN, [RIGHT]: HIDDEN, [PEND]: "team" } });
36→  const byId = (a, b) => a[0].localeCompare(b[0]);
37→  assert.deepEqual(plan.changes.map((c) => [c.asset_id, c.to]).sort(byId), [[WRONG, "team"], [RIGHT, "team"]].sort(byId));
38→  assert.ok(plan.changes.every((c) => /reset to baseline/.test(c.because)));
39→});
